def find_numbers_with_lcm_in_range(a, b, lower_bound, upper_bound):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def lcm(x, y):
        return x * y // gcd(x, y)

    for i in range(lower_bound, upper_bound + 1):
        for j in range(i + 1, upper_bound + 1):
            if lcm(i, j) >= a and lcm(i, j) <= b:
                return i, j
    return None
