def babylonian_sqrt(n, tolerance=1e-10, max_iterations=1000):
    if n < 0:
        raise ValueError("Cannot compute square root of a negative number")
    if n == 0:
        return 0
    guess = n
    while max_iterations > 0:
        improved_guess = (guess + n / guess) / 2
        if abs(guess - improved_guess) < tolerance:
            return improved_guess
        guess = improved_guess
        max_iterations -= 1
    raise RuntimeError("Failed to converge to a solution")
```

