def longest_palindromic_subsequence(s: str) -> str:
    n = len(s)
    dp = [["" for _ in range(n)] for _ in range(n)]

    for i in range(n):
        dp[i][i] = s[i]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and length == 2:
                dp[i][j] = s[i] + s[j]
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + s[i]
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j], key=len)

    return dp[0][n - 1]
