def max_sum_increasing_subsequence(arr, k):
    n = len(arr)
    dp = [0] * n
    dp[0] = arr[0]
    for i in range(1, n):
        dp[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]
    max_sum = max(dp)
    for i in range(n):
        if dp[i] == max_sum:
            break
    for j in range(k, n):
        if arr[j] > arr[i] and dp[i] + arr[j] > max_sum:
            max_sum = dp[i] + arr[j]
    return max_sum
